import math
import itertools
from fractions import Fraction

def num(x):
    # a negative number goes in parentheses, as you'd write it by hand
    if x < 0:
        return f"({x})"
    return f"{x}"

def arith(a0, d, n):
    print(f"  a_{n} = a_0 + n d = {a0} + {n} * {num(d)} = {a0 + n * d}")

def geo(a0, r, n):
    print(f"  a_{n} = a_0 r^n = {a0} * {num(r)}^{n} = {a0 * r ** n}")

def perm(n, k):
    if k > n:
        print(f"  P({n}, {k}) = 0, since {k} spots can't each get a different one of {n}")
        return
    print(f"  P({n}, {k}) = {n}!/{n - k}! = {math.factorial(n)}/{math.factorial(n - k)} = {math.perm(n, k)}")

def comb(n, k):
    print(f"  C({n}, {k}) = P({n}, {k})/{k}! = {math.perm(n, k)}/{math.factorial(k)} = {math.comb(n, k)}")

def dice(t):
    pairs = [p for p in itertools.product(range(1, 7), repeat=2) if p[0] + p[1] == t]
    print(f"  pairs: {pairs}")
    print(f"  P(sum = {t}) = {len(pairs)}/36 = {Fraction(len(pairs), 36)}")

def run(kind, nums):
    if kind == "arith":
        arith(nums[0], nums[1], nums[2])
    elif kind == "geo":
        geo(nums[0], nums[1], nums[2])
    elif kind == "perm":
        perm(nums[0], nums[1])
    elif kind == "comb":
        comb(nums[0], nums[1])
    else:
        dice(nums[0])

problems = [
    ("arith", [4, 7, 20]),
    ("perm", [10, 3]),
    ("geo", [2, 3, 6]),
    ("dice", [9]),
    ("comb", [9, 4]),
    ("arith", [50, -3, 17]),
    ("perm", [3, 5]),
    ("geo", [5, -2, 5]),
    ("comb", [8, 3]),
    ("dice", [13]),
]
for i in range(len(problems)):
    kind, nums = problems[i]
    print(f"Problem {i + 1}: {kind} {nums}")
    run(kind, nums)

